// Extracts the builder's own assembly engine + site CSS from the Rank Expand
// Academy builder HTML, so the site is generated by their code, not a rewrite.
const fs = require('fs');
const path = require('path');

const BUILDER = 'C:/Users/DELL/OneDrive/Desktop/Emergency Locksmith/Microsite Builder - Rank Expand Academy.html';
const OUT = path.join(__dirname, 'engine.js');

const html = fs.readFileSync(BUILDER, 'utf8');
const start = html.indexOf('/* ====== embedded assembly engine');
const end = html.indexOf('/* ====== wizard state');

if (start < 0 || end < 0 || end <= start) {
  throw new Error('Could not locate the engine block in the builder file');
}

let engine = html.slice(start, end);
engine += '\nmodule.exports.SITE_CSS = SITE_CSS;\nmodule.exports.SITE_JS = SITE_JS;\n';

fs.writeFileSync(OUT, engine, 'utf8');
console.log('engine extracted:', engine.length, 'bytes ->', OUT);
